import os
import random
import cocotb
from cocotb.clock import Clock
from cocotb.triggers import RisingEdge, Timer

try:
    from scoreboard import Scoreboard
except Exception:
    Scoreboard = None

try:
    from coverage_model import CoverageModel
except Exception:
    CoverageModel = None


def _seed() -> int:
    env = os.getenv("RANDOM_SEED")
    if env and env.isdigit():
        return int(env)
    return 1


async def _advance_time(dut):
    clocks = ['clk']
    for clk_name in clocks:
        if hasattr(dut, clk_name):
            await RisingEdge(getattr(dut, clk_name))
            # RisingEdge wakes in the signal-update phase, before clocked
            # nonblocking assignments and dependent combinational logic are
            # guaranteed observable. Move beyond that edge before sampling or
            # driving the next scenario step.
            await Timer(1, units="ns")
            return
    await Timer(10, units="ns")


def _safe_drive_random(sig, width_expr: str):
    try:
        width = int(width_expr)
    except Exception:
        try:
            width = len(sig.value.binstr)
        except Exception:
            width = 1
    width = max(int(width), 1)
    sig.value = random.getrandbits(width)


def _fit_to_signal(sig, value: int) -> int:
    try:
        width = len(sig)
    except Exception:
        try:
            width = len(sig.value.binstr)
        except Exception:
            width = 32
    width = max(int(width), 1)
    return int(value) & ((1 << width) - 1)


def _assert_outputs_known(dut, observable_outputs):
    for p in observable_outputs:
        name = p.get("name")
        if not name or not hasattr(dut, name):
            continue
        sig = getattr(dut, name)
        value = str(sig.value).lower()
        assert "x" not in value and "z" not in value, f"Output {name} is unknown/high-Z: {sig.value}"


@cocotb.test()
async def smoke_test(dut):
    """Basic smoke test: clock/reset bring-up and brief settle window."""
    seed = _seed()
    random.seed(seed)

    if hasattr(dut, "clk"):
        cocotb.start_soon(Clock(getattr(dut, "clk"), 10, units='ns').start())

    if hasattr(dut, "reset_n"):
        getattr(dut, "reset_n").value = 0
    await _advance_time(dut)
    if hasattr(dut, "reset_n"):
        getattr(dut, "reset_n").value = 1
    await Timer(5, units='ns')

    # Initialize discoverable DUT inputs from spec
    if hasattr(dut, "enable"):
        getattr(dut, "enable").value = 0
    if hasattr(dut, "duty_cycle"):
        getattr(dut, "duty_cycle").value = 0
    if hasattr(dut, "period"):
        getattr(dut, "period").value = 0

    await Timer(20, units="ns")

    sb = Scoreboard(dut) if Scoreboard else None
    cov = CoverageModel() if CoverageModel else None

    if sb:
        sb.start()
    if cov:
        cov.start(dut)

    for _ in range(5):
        await _advance_time(dut)
        if cov:
            try:
                cov.sample()
            except Exception:
                pass

    _assert_outputs_known(dut, [{"name": "pwm_out", "width_expr": "1"}, {"name": "counter_value", "width_expr": "8"}])

    if cov:
        try:
            cov.stop()
            cov.write_reports()
        except Exception:
            pass

    

    if sb:
        sb.stop()


